From 1439e81b368a2ac414d727fc5ea59e7263f6164f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:41:48 +0100
Subject: [PATCH] applets/appmenu: add option to only show menus for maximized
 windows

With focus follows mouse, the global menu only works for windows that
touch the panel, so for the others it is just clutter. A new option in
the settings hides the menu while the active window isn't maximized.

BUG: 510765
---
 applets/appmenu/appmenumodel.cpp      | 24 +++++++++++++++++++++++-
 applets/appmenu/appmenumodel.h        |  6 ++++++
 applets/appmenu/main.xml              |  5 +++++
 applets/appmenu/qml/configGeneral.qml |  6 ++++++
 applets/appmenu/qml/main.qml          |  1 +
 5 files changed, 41 insertions(+), 1 deletion(-)

diff --git a/applets/appmenu/appmenumodel.cpp b/applets/appmenu/appmenumodel.cpp
index e91d858062..07b185510a 100644
--- a/applets/appmenu/appmenumodel.cpp
+++ b/applets/appmenu/appmenumodel.cpp
@@ -52,7 +52,8 @@ AppMenuModel::AppMenuModel(QObject *parent)
                 Q_UNUSED(topLeft)
                 Q_UNUSED(bottomRight)
                 if (roles.contains(TaskManager::AbstractTasksModel::ApplicationMenuObjectPath)
-                    || roles.contains(TaskManager::AbstractTasksModel::ApplicationMenuServiceName) || roles.isEmpty()) {
+                    || roles.contains(TaskManager::AbstractTasksModel::ApplicationMenuServiceName)
+                    || roles.contains(TaskManager::AbstractTasksModel::IsMaximized) || roles.isEmpty()) {
                     onActiveWindowChanged();
                 }
             });
@@ -148,6 +149,22 @@ void AppMenuModel::setallScreens(bool allScreens)
     Q_EMIT allScreensChanged();
 }

+bool AppMenuModel::maximizedOnly() const
+{
+    return m_maximizedOnly;
+}
+
+void AppMenuModel::setMaximizedOnly(bool maximizedOnly)
+{
+    if (m_maximizedOnly == maximizedOnly) {
+        return;
+    }
+
+    m_maximizedOnly = maximizedOnly;
+    onActiveWindowChanged();
+    Q_EMIT maximizedOnlyChanged();
+}
+
 bool AppMenuModel::visible() const
 {
     return m_visible;
@@ -220,6 +237,11 @@ void AppMenuModel::onActiveWindowChanged()
     }

     const QModelIndex activeTaskIndex = m_tasksModel->activeTask();
+    if (m_maximizedOnly && !m_tasksModel->data(activeTaskIndex, TaskManager::AbstractTasksModel::IsMaximized).toBool()) {
+        updateApplicationMenu(QString(), QString());
+        return;
+    }
+
     const QString objectPath = m_tasksModel->data(activeTaskIndex, TaskManager::AbstractTasksModel::ApplicationMenuObjectPath).toString();
     const QString serviceName = m_tasksModel->data(activeTaskIndex, TaskManager::AbstractTasksModel::ApplicationMenuServiceName).toString();
     updateApplicationMenu(serviceName, objectPath);
diff --git a/applets/appmenu/appmenumodel.h b/applets/appmenu/appmenumodel.h
index ba4a64eaa1..7859450ff7 100644
--- a/applets/appmenu/appmenumodel.h
+++ b/applets/appmenu/appmenumodel.h
@@ -32,6 +32,7 @@ class AppMenuModel : public QAbstractListModel
     Q_PROPERTY(bool menuAvailable READ menuAvailable WRITE setMenuAvailable NOTIFY menuAvailableChanged)
     Q_PROPERTY(bool visible READ visible NOTIFY visibleChanged)
     Q_PROPERTY(bool allScreens READ allScreens WRITE setallScreens NOTIFY allScreensChanged)
+    Q_PROPERTY(bool maximizedOnly READ maximizedOnly WRITE setMaximizedOnly NOTIFY maximizedOnlyChanged)

     Q_PROPERTY(Plasma::Types::ItemStatus containmentStatus MEMBER m_containmentStatus NOTIFY containmentStatusChanged)
     Q_PROPERTY(QRect screenGeometry READ screenGeometry WRITE setScreenGeometry NOTIFY screenGeometryChanged)
@@ -57,6 +58,9 @@ public:
     bool allScreens() const;
     void setallScreens(bool allScreens);

+    bool maximizedOnly() const;
+    void setMaximizedOnly(bool maximizedOnly);
+
     bool visible() const;

     QRect screenGeometry() const;
@@ -76,6 +80,7 @@ private Q_SLOTS:

 Q_SIGNALS:
     void allScreensChanged();
+    void maximizedOnlyChanged();
     void menuAvailableChanged();
     void modelNeedsUpdate();
     void containmentStatusChanged();
@@ -85,6 +90,7 @@ Q_SIGNALS:
 private:
     bool m_menuAvailable;
     bool m_allScreens = true;
+    bool m_maximizedOnly = false;
     bool m_updatePending = false;
     bool m_visible = true;

diff --git a/applets/appmenu/main.xml b/applets/appmenu/main.xml
index 6260e1e159..10674f7eca 100644
--- a/applets/appmenu/main.xml
+++ b/applets/appmenu/main.xml
@@ -15,6 +15,11 @@
       <label>Whether to show menus for apps on all screens, instead of just the one with the applet.</label>
       <default>true</default>
     </entry>
+
+    <entry name="maximizedOnly" type="Bool">
+      <label>Whether to only show menus for maximized windows.</label>
+      <default>false</default>
+    </entry>
   </group>

 </kcfg>
diff --git a/applets/appmenu/qml/configGeneral.qml b/applets/appmenu/qml/configGeneral.qml
index 84be2ca86f..0eb47bb3e5 100644
--- a/applets/appmenu/qml/configGeneral.qml
+++ b/applets/appmenu/qml/configGeneral.qml
@@ -14,6 +14,7 @@ import org.kde.kcmutils as KCM
 KCM.SimpleKCM {
     property alias cfg_compactView: compactViewRadioButton.checked
     property alias cfg_allScreens: allScreensCheckBox.checked
+    property alias cfg_maximizedOnly: maximizedOnlyCheckBox.checked

     Kirigami.FormLayout {
         RadioButton {
@@ -31,5 +32,10 @@ KCM.SimpleKCM {
             id: allScreensCheckBox
             text: i18n("Show menus for apps on different screens")
         }
+
+        CheckBox {
+            id: maximizedOnlyCheckBox
+            text: i18n("Show menus only for maximized windows")
+        }
     }
 }
diff --git a/applets/appmenu/qml/main.qml b/applets/appmenu/qml/main.qml
index e9f5280a3f..8edce9b157 100644
--- a/applets/appmenu/qml/main.qml
+++ b/applets/appmenu/qml/main.qml
@@ -148,6 +148,7 @@ PlasmoidItem {
         containmentStatus: Plasmoid.containment.status
         screenGeometry: root.screenGeometry
         allScreens: Plasmoid.configuration.allScreens
+        maximizedOnly: Plasmoid.configuration.maximizedOnly
         onRequestActivateIndex: Plasmoid.requestActivateIndex(index)
         Component.onCompleted: {
             Plasmoid.model = appMenuModel;
-- 
